import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class StdKeyDeserializer_deserializeKey_TriageGen2Test {

    private DeserializationContext mockCtxt;
    private DeserializationConfig mockConfig;

    // Concrete implementation to allow testing the protected _parse method
    private static class TestKeyDeserializer extends StdKeyDeserializer {
        private final Object parseResult;
        private final Exception parseException;

        public TestKeyDeserializer(Class<?> cls, Object parseResult, Exception parseException) {
            super(0, cls);
            this.parseResult = parseResult;
            this.parseException = parseException;
        }

        @Override
        protected Object _parse(String key, DeserializationContext ctxt) throws Exception {
            if (parseException != null) {
                throw parseException;
            }
            return parseResult;
        }
    }

    @Before
    public void setUp() {
        mockCtxt = mock(DeserializationContext.class);
        mockConfig = mock(DeserializationConfig.class);
        when(mockCtxt.getConfig()).thenReturn(mockConfig);
    }

    @Test
    public void testDeserializeKey_NullKey() throws IOException {
        StdKeyDeserializer deserializer = new TestKeyDeserializer(String.class, "val", null);
        Object result = deserializer.deserializeKey(null, mockCtxt);
        assertNull(result);
    }

    @Test
    public void testDeserializeKey_SuccessfulParse() throws IOException {
        String key = "testKey";
        Object expected = 123;
        StdKeyDeserializer deserializer = new TestKeyDeserializer(Integer.class, expected, null);

        Object result = deserializer.deserializeKey(key, mockCtxt);

        assertEquals(expected, result);
    }

    @Test
    public void testDeserializeKey_ParseReturnsNull_NotEnum() throws IOException {
        String key = "testKey";
        StdKeyDeserializer deserializer = new TestKeyDeserializer(String.class, null, null);

        when(mockCtxt.handleWeirdKey(eq(String.class), eq(key), anyString())).thenReturn("weird_value");

        Object result = deserializer.deserializeKey(key, mockCtxt);

        assertEquals("weird_value", result);
        verify(mockCtxt).handleWeirdKey(eq(String.class), eq(key), contains("not a valid representation"));
    }

    @Test
    public void testDeserializeKey_ParseReturnsNull_IsEnum_FeatureEnabled() throws IOException {
        enum TestEnum { A, B }
        String key = "UNKNOWN";
        StdKeyDeserializer deserializer = new TestKeyDeserializer(TestEnum.class, null, null);

        when(mockConfig.isEnabled(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL)).thenReturn(true);

        Object result = deserializer.deserializeKey(key, mockCtxt);

        assertNull(result);
    }

    @Test
    public void testDeserializeKey_ParseReturnsNull_IsEnum_FeatureDisabled() throws IOException {
        enum TestEnum { A, B }
        String key = "UNKNOWN";
        StdKeyDeserializer deserializer = new TestKeyDeserializer(TestEnum.class, null, null);

        when(mockConfig.isEnabled(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL)).thenReturn(false);
        when(mockCtxt.handleWeirdKey(eq(TestEnum.class), eq(key), anyString())).thenReturn("error_obj");

        Object result = deserializer.deserializeKey(key, mockCtxt);

        assertEquals("error_obj", result);
        verify(mockCtxt).handleWeirdKey(eq(TestEnum.class), eq(key), contains("not a valid representation"));
    }

    @Test
    public void testDeserializeKey_ExceptionThrown() throws IOException {
        String key = "badKey";
        RuntimeException exception = new RuntimeException("parsing error");
        StdKeyDeserializer deserializer = new TestKeyDeserializer(String.class, null, exception);

        String errorMsg = "not a valid representation, problem: (%s) %s";
        when(mockCtxt.handleWeirdKey(eq(String.class), eq(key), anyString())).thenReturn("exception_handled");

        Object result = deserializer.deserializeKey(key, mockCtxt);

        assertEquals("exception_handled", result);
        // Verify the specific error message format used in the catch block
        verify(mockCtxt).handleWeirdKey(
                eq(String.class), 
                eq(key), 
                argThat(s -> s.contains("RuntimeException") && s.contains("parsing error"))
        );
    }
}
